-- ═════════════════════════════════════════════════════════════════════════════
-- Hand-written below: rules Prisma's schema language cannot express.
-- Covered by apps/api/test/database.e2e-spec.ts and scheduling.e2e-spec.ts.
-- ═════════════════════════════════════════════════════════════════════════════

-- ── Session time zone (§16.2) ──────────────────────────────────────────────
-- Prisma's Postgres driver adapter writes `timestamptz` values as UTC wall-clock
-- text and reads them back as UTC, so every session must run in UTC (Supabase's
-- default). Pinning it for the database keeps a server configured otherwise
-- (e.g. a local cluster initialized in Africa/Cairo) from skewing stored instants
-- and from disagreeing with SQL-side time arithmetic such as `now()`.
DO $$
BEGIN
  EXECUTE format('ALTER DATABASE %I SET timezone TO %L', current_database(), 'UTC');
EXCEPTION WHEN insufficient_privilege THEN
  RAISE NOTICE 'Could not pin the database time zone to UTC; make sure SHOW timezone returns UTC.';
END $$;

-- ── Training program: one current program; every value in range (§6.1, §8.1, §11) ──
CREATE UNIQUE INDEX "training_programs_one_current" ON "training_programs" ("is_current") WHERE "is_current";
ALTER TABLE "training_programs"
  ADD CONSTRAINT "training_programs_values" CHECK (
    "name" = btrim("name") AND "name" <> '' AND
    "duration_weeks" BETWEEN 1 AND 52 AND
    "allowed_absences" BETWEEN 0 AND 100);
ALTER TABLE "training_programs"
  ADD CONSTRAINT "training_programs_timing" CHECK (
    "check_in_opens_minutes" BETWEEN 0 AND 240 AND
    "grace_minutes" BETWEEN 0 AND 240 AND
    "check_in_closes_minutes" BETWEEN 1 AND 720 AND
    "grace_minutes" <= "check_in_closes_minutes");
-- An unknown zone name makes timezone() raise, so only real IANA zones are stored.
ALTER TABLE "training_programs"
  ADD CONSTRAINT "training_programs_time_zone" CHECK (timezone("time_zone", TIMESTAMP '2000-01-01') IS NOT NULL);

-- ── Recurring schedules (§6.1, §11.2) ──────────────────────────────────────
CREATE FUNCTION "ftms_distinct_count"(values_ SMALLINT[]) RETURNS INTEGER
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$ SELECT count(DISTINCT v)::INTEGER FROM unnest(values_) v $$;

ALTER TABLE "training_schedules" ALTER COLUMN "weekdays" SET NOT NULL;
ALTER TABLE "training_schedules"
  ADD CONSTRAINT "training_schedules_values" CHECK (
    "title" = btrim("title") AND "title" <> '' AND
    cardinality("weekdays") BETWEEN 1 AND 7 AND
    "weekdays" <@ ARRAY[0, 1, 2, 3, 4, 5, 6]::SMALLINT[] AND
    "ftms_distinct_count"("weekdays") = cardinality("weekdays") AND
    ("end_time" IS NULL OR "end_time" > "start_time") AND
    "ends_on" >= "starts_on" AND
    ("location_name" IS NULL OR ("location_name" = btrim("location_name") AND "location_name" <> '')));
ALTER TABLE "training_schedules"
  ADD CONSTRAINT "training_schedules_ended" CHECK (("ended_at" IS NULL) = ("end_reason" IS NULL));

-- An ended schedule is history: only foreign-key SET NULL of actor columns may touch it.
CREATE FUNCTION "ftms_check_schedule_final"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD."ended_at" IS NOT NULL AND (
       (to_jsonb(NEW) - 'ended_by_id' - 'created_by_id' - 'updated_at')
         IS DISTINCT FROM (to_jsonb(OLD) - 'ended_by_id' - 'created_by_id' - 'updated_at')
       OR (NEW."ended_by_id" IS DISTINCT FROM OLD."ended_by_id" AND NEW."ended_by_id" IS NOT NULL)
       OR (NEW."created_by_id" IS DISTINCT FROM OLD."created_by_id" AND NEW."created_by_id" IS NOT NULL)) THEN
    RAISE EXCEPTION 'schedule % has ended and can no longer change', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER "training_schedules_final"
  BEFORE UPDATE ON "training_schedules"
  FOR EACH ROW EXECUTE FUNCTION "ftms_check_schedule_final"();

-- ── Groups of schedules and visits: never archived ones; never none (§6.2) ──
CREATE FUNCTION "ftms_check_target_group"() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  group_archived TIMESTAMPTZ(3);
BEGIN
  SELECT "archived_at" INTO group_archived FROM "training_groups" WHERE "id" = NEW."group_id" FOR SHARE;
  IF group_archived IS NOT NULL THEN
    RAISE EXCEPTION 'group % is archived', NEW."group_id" USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER "schedule_groups_target_check"
  BEFORE INSERT OR UPDATE OF "group_id" ON "schedule_groups"
  FOR EACH ROW EXECUTE FUNCTION "ftms_check_target_group"();
CREATE TRIGGER "visit_groups_target_check"
  BEFORE INSERT OR UPDATE OF "group_id" ON "visit_groups"
  FOR EACH ROW EXECUTE FUNCTION "ftms_check_target_group"();

-- Checked at COMMIT, so a visit (or schedule) and its groups are written together.
CREATE FUNCTION "ftms_check_visit_has_groups"() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  target UUID;
BEGIN
  IF TG_TABLE_NAME = 'training_visits' THEN
    target := NEW."id";
  ELSE
    target := OLD."visit_id";
  END IF;
  IF EXISTS (SELECT 1 FROM "training_visits" WHERE "id" = target)
     AND NOT EXISTS (SELECT 1 FROM "visit_groups" WHERE "visit_id" = target) THEN
    RAISE EXCEPTION 'visit % must concern at least one group', target USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END $$;

CREATE CONSTRAINT TRIGGER "training_visits_has_groups"
  AFTER INSERT ON "training_visits"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION "ftms_check_visit_has_groups"();
CREATE CONSTRAINT TRIGGER "visit_groups_not_last"
  AFTER DELETE OR UPDATE OF "visit_id" ON "visit_groups"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION "ftms_check_visit_has_groups"();

CREATE FUNCTION "ftms_check_schedule_has_groups"() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  target UUID;
BEGIN
  IF TG_TABLE_NAME = 'training_schedules' THEN
    target := NEW."id";
  ELSE
    target := OLD."schedule_id";
  END IF;
  IF EXISTS (SELECT 1 FROM "training_schedules" WHERE "id" = target)
     AND NOT EXISTS (SELECT 1 FROM "schedule_groups" WHERE "schedule_id" = target) THEN
    RAISE EXCEPTION 'schedule % must concern at least one group', target USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END $$;

CREATE CONSTRAINT TRIGGER "training_schedules_has_groups"
  AFTER INSERT ON "training_schedules"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION "ftms_check_schedule_has_groups"();
CREATE CONSTRAINT TRIGGER "schedule_groups_not_last"
  AFTER DELETE OR UPDATE OF "schedule_id" ON "schedule_groups"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION "ftms_check_schedule_has_groups"();

-- ── Schedule exceptions: one per day (all schedules) or per schedule and day ──
CREATE UNIQUE INDEX "schedule_exceptions_one_per_day"
  ON "schedule_exceptions" ("program_id", "date") WHERE "schedule_id" IS NULL;
CREATE UNIQUE INDEX "schedule_exceptions_one_per_schedule_day"
  ON "schedule_exceptions" ("schedule_id", "date") WHERE "schedule_id" IS NOT NULL;
ALTER TABLE "schedule_exceptions"
  ADD CONSTRAINT "schedule_exceptions_reason" CHECK ("reason" = btrim("reason") AND length("reason") >= 3);

-- ── Visits (§6.3, §6.5, §8.1, §16.2) ───────────────────────────────────────
ALTER TABLE "training_visits"
  ADD CONSTRAINT "training_visits_values" CHECK (
    "title" = btrim("title") AND "title" <> '' AND
    ("description" IS NULL OR length("description") <= 5000) AND
    ("end_time" IS NULL OR "end_time" > "start_time") AND
    ("location_name" IS NULL OR ("location_name" = btrim("location_name") AND "location_name" <> '')));
ALTER TABLE "training_visits"
  ADD CONSTRAINT "training_visits_coordinates" CHECK (
    ("latitude" IS NULL) = ("longitude" IS NULL) AND
    ("latitude" IS NULL OR ("latitude" BETWEEN -90 AND 90 AND "longitude" BETWEEN -180 AND 180)));
ALTER TABLE "training_visits"
  ADD CONSTRAINT "training_visits_map_url" CHECK ("map_url" IS NULL OR "map_url" ~ '^https://\S+$');
ALTER TABLE "training_visits"
  ADD CONSTRAINT "training_visits_timing" CHECK (
    "check_in_opens_minutes" BETWEEN 0 AND 240 AND
    "grace_minutes" BETWEEN 0 AND 240 AND
    "check_in_closes_minutes" BETWEEN 1 AND 720 AND
    "grace_minutes" <= "check_in_closes_minutes");
ALTER TABLE "training_visits"
  ADD CONSTRAINT "training_visits_occurrence" CHECK (("schedule_id" IS NULL) = ("occurrence_date" IS NULL));
-- A cancelled visit keeps its status, time and reason (§6.5): it never silently disappears.
ALTER TABLE "training_visits"
  ADD CONSTRAINT "training_visits_status" CHECK (
    ("status" = 'SCHEDULED' AND "cancelled_at" IS NULL AND "cancel_reason" IS NULL
       AND "cancelled_by_exception_id" IS NULL) OR
    ("status" = 'CANCELLED' AND "cancelled_at" IS NOT NULL AND "cancel_reason" IS NOT NULL));

-- The UTC instants are derived here from the wall-clock date and times in the
-- program's time zone (§16.2), so they can never disagree with what students see.
CREATE FUNCTION "ftms_visit_instants"() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  zone TEXT;
BEGIN
  SELECT "time_zone" INTO zone FROM "training_programs" WHERE "id" = NEW."program_id";
  NEW."starts_at" := (NEW."date" + NEW."start_time") AT TIME ZONE zone;
  NEW."ends_at" := CASE WHEN NEW."end_time" IS NULL THEN NULL
                        ELSE (NEW."date" + NEW."end_time") AT TIME ZONE zone END;
  RETURN NEW;
END $$;

CREATE TRIGGER "training_visits_instants"
  BEFORE INSERT OR UPDATE OF "date", "start_time", "end_time", "program_id", "starts_at", "ends_at"
  ON "training_visits"
  FOR EACH ROW EXECUTE FUNCTION "ftms_visit_instants"();

-- ── Visit files: at most one cover photo; private buckets only (§16.3) ─────
CREATE UNIQUE INDEX "visit_files_one_cover" ON "visit_files" ("visit_id") WHERE "kind" = 'COVER';
ALTER TABLE "visit_files"
  ADD CONSTRAINT "visit_files_values" CHECK (
    "size_bytes" > 0 AND btrim("file_name") <> '' AND
    "bucket" IN ('visit-media', 'visit-documents') AND
    ("kind" <> 'COVER' OR "bucket" = 'visit-media'));

-- ── Notifications (§12): idempotent per recipient; only `read_at` ever changes ──
CREATE INDEX "notifications_unread" ON "notifications" ("recipient_id") WHERE "read_at" IS NULL;
ALTER TABLE "notifications"
  ADD CONSTRAINT "notifications_values" CHECK (
    jsonb_typeof("data") = 'object' AND
    "type" ~ '^[a-z_]+\.[a-z_]+$' AND
    ("link" IS NULL OR "link" ~ '^/[A-Za-z0-9]') AND
    ("read_at" IS NULL OR "read_at" >= "created_at"));

CREATE FUNCTION "ftms_check_notification_update"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF (to_jsonb(NEW) - 'read_at') IS DISTINCT FROM (to_jsonb(OLD) - 'read_at') THEN
    RAISE EXCEPTION 'notification % is immutable except for its read time', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER "notifications_immutable"
  BEFORE UPDATE ON "notifications"
  FOR EACH ROW EXECUTE FUNCTION "ftms_check_notification_update"();

-- ── Row Level Security (Supabase Data API gets nothing; see Phase 1) ────────
ALTER TABLE "training_programs" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "training_schedules" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "schedule_groups" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "schedule_exceptions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "training_visits" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "visit_groups" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "visit_files" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "notifications" ENABLE ROW LEVEL SECURITY;

DO $$
DECLARE
  api_role TEXT;
BEGIN
  FOREACH api_role IN ARRAY ARRAY['anon', 'authenticated'] LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = api_role) THEN
      EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA public FROM %I', api_role);
      EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM %I', api_role);
    END IF;
  END LOOP;
END $$;
